import type { BankQuestion } from "@/lib/bank";

/** Amines, Biomolecules and Polymers (Chemistry (JEE/NEET)): 118 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-amines-biomolecules-1","question":"Hinsberg's reagent, used to distinguish primary, secondary and tertiary amines, is:","options":["Benzoyl chloride","Acetyl chloride","Benzenesulphonyl chloride","Chloroform with alcoholic KOH"],"answer":2,"explanation":"C₆H₅SO₂Cl gives an alkali-soluble sulphonamide with 1° amines, an insoluble one with 2° amines and no reaction with 3° amines.","difficulty":"easy","source":"NEET"},
  {"id":"chem-amines-biomolecules-2","question":"Which of the following vitamins is water-soluble?","options":["Vitamin C","Vitamin D","Vitamin A","Vitamin K"],"answer":0,"explanation":"B-group vitamins and vitamin C are water-soluble; A, D, E and K are fat-soluble.","difficulty":"easy","source":"NEET"},
  {"id":"chem-amines-biomolecules-3","question":"The monomer of natural rubber is:","options":["Styrene","Isoprene (2-methylbuta-1,3-diene)","Buta-1,3-diene","Chloroprene"],"answer":1,"explanation":"Natural rubber is cis-1,4-polyisoprene. Chloroprene gives neoprene; butadiene with styrene gives Buna-S.","difficulty":"easy","source":"NEET"},
  {"id":"chem-amines-biomolecules-4","question":"Which of the following amines gives the carbylamine (isocyanide) test?","options":["Triethylamine","N,N-Dimethylaniline","Aniline","N-Methylaniline"],"answer":2,"explanation":"Only primary amines (aliphatic or aromatic) react with CHCl₃ and alcoholic KOH to give foul-smelling isocyanides.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-amines-biomolecules-5","question":"Gabriel phthalimide synthesis is used to prepare:","options":["Primary aromatic amines","Secondary amines","Tertiary amines","Primary aliphatic amines"],"answer":3,"explanation":"Potassium phthalimide is N-alkylated by an alkyl halide and then hydrolysed to RNH₂. Aryl halides do not undergo the SN2 step, so aromatic amines cannot be made.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-amines-biomolecules-6","question":"Propanamide treated with Br₂ and aqueous NaOH (Hoffmann bromamide degradation) gives:","options":["Ethanamine","Propanoic acid","Propanenitrile","Propanamine"],"answer":0,"explanation":"RCONH₂ + Br₂ + 4NaOH → RNH₂ + Na₂CO₃ + 2NaBr + 2H₂O: the amine has one carbon fewer than the amide.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-7","question":"Nylon-6,6 is made by condensation polymerisation of:","options":["Phenol and formaldehyde","Hexamethylenediamine and adipic acid","Ethylene glycol and terephthalic acid","Caprolactam"],"answer":1,"explanation":"H₂N(CH₂)₆NH₂ + HOOC(CH₂)₄COOH give the polyamide nylon-6,6 (6 carbons each). Caprolactam gives nylon-6.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-amines-biomolecules-8","question":"Glucose heated for a long time with HI gives n-hexane. This shows that glucose:","options":["Has its six carbon atoms in a straight chain","Contains five –OH groups","Contains an aldehyde group","Exists in a cyclic form"],"answer":0,"explanation":"Formation of n-hexane (not a branched alkane) proves the unbranched six-carbon chain.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-amines-biomolecules-9","question":"Which nitrogenous base is present in RNA but not in DNA?","options":["Uracil","Thymine","Cytosine","Guanine"],"answer":0,"explanation":"RNA contains A, G, C and U; DNA contains A, G, C and T.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-amines-biomolecules-10","question":"The correct order of basic strength of the ethylamines in aqueous solution is:","options":["(C₂H₅)₂NH > (C₂H₅)₃N > C₂H₅NH₂ > NH₃","C₂H₅NH₂ > (C₂H₅)₂NH > (C₂H₅)₃N > NH₃","NH₃ > C₂H₅NH₂ > (C₂H₅)₂NH > (C₂H₅)₃N","(C₂H₅)₃N > (C₂H₅)₂NH > C₂H₅NH₂ > NH₃"],"answer":0,"explanation":"In water, basicity depends on +I effect, solvation of the cation and steric hindrance together. For ethyl groups the order is 2° > 3° > 1° > NH₃ (for methyl it is 2° > 1° > 3°).","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-amines-biomolecules-11","question":"Benzenediazonium chloride is treated with hypophosphorous acid (H₃PO₂). The organic product is:","options":["Aniline","Benzene","Phenol","Chlorobenzene"],"answer":1,"explanation":"H₃PO₂ (or ethanol) replaces the –N₂⁺ group by H. Warm water would give phenol and CuCl/HCl would give chlorobenzene.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-12","question":"Benzenediazonium chloride reacts with phenol in mildly alkaline solution to give:","options":["Benzene and N₂","p-Hydroxyazobenzene, an orange dye","Chlorobenzene and phenol","Diphenyl ether"],"answer":1,"explanation":"Diazo coupling: the phenoxide ion is attacked at the para position by the electrophilic diazonium ion, forming an azo compound (–N=N–).","difficulty":"hard","source":"NEET"},
  {"id":"chem-amines-biomolecules-13","question":"Sucrose is a non-reducing sugar because:","options":["The glycosidic bond joins C1 of α-glucose to C2 of β-fructose, so neither anomeric carbon is free","It contains no –OH groups","It is a polysaccharide","It is made of two glucose units"],"answer":0,"explanation":"Both reducing groups (the aldehyde of glucose and the ketone of fructose) are tied up in the glycosidic linkage, so sucrose does not reduce Tollens' or Fehling's reagent.","difficulty":"hard","source":"NEET"},
  {"id":"chem-amines-biomolecules-14","question":"Direct nitration of aniline with a mixture of conc. HNO₃ and conc. H₂SO₄ gives a large amount of m-nitroaniline because:","options":["In strongly acidic medium aniline is protonated to the anilinium ion, which is meta-directing","The ortho and para positions are sterically blocked","Nitration always gives the meta product","The –NH₂ group is meta-directing"],"answer":0,"explanation":"–NH₃⁺ is electron-withdrawing and meta-directing; about 47% of the product is the meta isomer, along with p-nitroaniline and oxidation products.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-amines-biomolecules-15","question":"When a protein is denatured (for example, an egg boiled), which level of structure remains intact?","options":["Quaternary structure","Primary structure","Secondary structure","Tertiary structure"],"answer":1,"explanation":"Denaturation breaks H-bonds and other weak interactions, destroying the secondary and tertiary structure; the peptide-bond sequence (primary structure) survives.","difficulty":"hard","source":"NEET"},
  {"id":"chem-amines-biomolecules-16","question":"Which of the following polymers is biodegradable?","options":["PVC","Teflon","Bakelite","PHBV"],"answer":3,"explanation":"PHBV (poly-β-hydroxybutyrate-co-β-hydroxyvalerate) is broken down by bacteria. Nylon-2-nylon-6 is another biodegradable example; the others persist.","difficulty":"hard","source":"NEET"},
  {"id":"chem-amines-biomolecules-17","question":"In the vulcanisation of natural rubber, sulphur:","options":["Converts cis double bonds into trans","Breaks the double bonds into single bonds throughout","Acts only as a catalyst and is not incorporated","Forms cross-links between chains at the reactive allylic positions"],"answer":3,"explanation":"Heating rubber with sulphur at 373–415 K creates –S–S– bridges between chains, making it harder, less sticky and more elastic over a wider temperature range.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-18","question":"Which observation can NOT be explained by the open-chain structure of glucose?","options":["Glucose forms an oxime with hydroxylamine","Glucose is oxidised by bromine water to gluconic acid","Glucose forms a pentaacetate with acetic anhydride","Glucose pentaacetate does not react with hydroxylamine"],"answer":3,"explanation":"In the pentaacetate the anomeric –OH is acetylated, so no free –CHO can form; this, along with the two anomers and no reaction with NaHSO₃, points to the cyclic hemiacetal structure.","difficulty":"hard","source":"NEET"},
  {"id":"chem-amines-biomolecules-19","question":"How many of the following statements are correct? (A) Aniline does not undergo Friedel–Crafts reaction. (B) Aniline has a lower pKb than methylamine. (C) Tertiary amines do not react with Hinsberg's reagent. (D) Aromatic primary amines cannot be prepared by Gabriel phthalimide synthesis.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A (–NH₂ forms a salt with AlCl₃), C and D are correct. B is wrong: aniline is the weaker base, so its pKb (9.4) is higher than that of methylamine (3.4).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-20","question":"Assertion (A): In aqueous solution, (CH₃)₃N is a weaker base than (CH₃)₂NH. Reason (R): The three methyl groups hinder hydrogen-bonded solvation of the protonated amine, (CH₃)₃NH⁺.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both true: although +I effect favours the 3° amine, its cation has only one N–H for H-bonding with water and is poorly stabilised, so 2° wins in water.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-amines-biomolecules-21","question":"Match the polymer (Column I) with its description (Column II). (a) Bakelite, (b) Nylon-6, (c) Buna-S, (d) Terylene. (1) Addition copolymer; (2) Thermosetting polymer; (3) Polyamide from caprolactam; (4) Polyester of ethylene glycol and terephthalic acid.","options":["a-1, b-3, c-2, d-4","a-2, b-4, c-1, d-3","a-3, b-2, c-1, d-4","a-2, b-3, c-1, d-4"],"answer":3,"explanation":"Bakelite (phenol–formaldehyde) is thermosetting; nylon-6 comes from caprolactam; Buna-S is a butadiene–styrene addition copolymer; Terylene (Dacron) is a polyester.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-amines-biomolecules-22","question":"The number of stereocentres (chiral carbons) in α-D-glucopyranose is:","options":["5","3","6","4"],"answer":0,"explanation":"Open-chain glucose has 4 chiral carbons (C2–C5). Ring closure makes C1 (the anomeric carbon) chiral too, giving 5.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-amines-biomolecules-23","question":"Benzene is treated in turn with (i) conc. HNO₃/conc. H₂SO₄, (ii) Sn/HCl, (iii) NaNO₂/HCl at 273–278 K, (iv) CuCN/KCN and (v) H₃O⁺ with heating. The final product is:","options":["Benzamide","Phenol","Benzonitrile","Benzoic acid"],"answer":3,"explanation":"Nitrobenzene → aniline → benzenediazonium chloride → benzonitrile (Sandmeyer) → benzoic acid on complete hydrolysis.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-24","question":"The total number of structurally isomeric amines with the molecular formula C₄H₁₁N is:","options":["7","9","8","6"],"answer":2,"explanation":"Primary: butan-1-amine, butan-2-amine, 2-methylpropan-1-amine, 2-methylpropan-2-amine (4). Secondary: N-methylpropan-1-amine, N-methylpropan-2-amine, N-ethylethanamine (3). Tertiary: N,N-dimethylethanamine (1). Total 8.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-25","question":"How many of the following statements are correct? (A) Vitamin B₁₂ is the water-soluble vitamin that can be stored in the body. (B) In DNA, guanine pairs with cytosine through two hydrogen bonds. (C) Amylose is highly branched whereas amylopectin is linear. (D) Cellulose is a linear polymer of β-D-glucose units.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A and D are correct. B is wrong: G≡C has three H-bonds (A=T has two). C is reversed: amylose is linear (α-1,4) and amylopectin is branched (α-1,6 branches).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-26","question":"How many different tripeptides can be formed from glycine, alanine and valine if each amino acid is used exactly once in every tripeptide?","options":["9","27","6","3"],"answer":2,"explanation":"The sequence matters (N-terminus to C-terminus), so the number is 3! = 6. 27 would allow repetition.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-27","question":"Which of the following amines does NOT liberate nitrogen gas when treated with nitrous acid at room temperature?","options":["Ethanamine","Propan-1-amine","2-Methylpropan-2-amine","N-Methylmethanamine"],"answer":3,"explanation":"Primary aliphatic amines (including the tertiary-alkyl 2-methylpropan-2-amine) form unstable diazonium salts that release N₂. The secondary amine (CH₃)₂NH gives a yellow N-nitrosamine instead.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-28","question":"Which pair of sugars gives the same osazone with excess phenylhydrazine?","options":["Glucose and ribose","Glucose and galactose","Fructose and sucrose","Glucose and fructose"],"answer":3,"explanation":"Osazone formation involves C1 and C2 only. Glucose and fructose differ only there, so their osazones are identical; galactose differs at C4 and gives a different osazone.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-29","question":"Assertion (A): Sucrose is dextrorotatory, but after hydrolysis the mixture becomes laevorotatory. Reason (R): Fructose is dextrorotatory and rotates the plane of polarised light more strongly than glucose.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true (inversion of cane sugar). R is false: fructose is laevorotatory (−92.4°), and its rotation outweighs that of dextrorotatory glucose (+52.5°), which is what makes invert sugar laevorotatory.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-amines-biomolecules-30","question":"How many of the following are addition polymers: PVC, Teflon, nylon-6,6, Bakelite, polyacrylonitrile, Terylene, Buna-N?","options":["4","2","3","5"],"answer":0,"explanation":"PVC, Teflon, polyacrylonitrile and Buna-N form by addition across C=C. Nylon-6,6, Bakelite and Terylene are condensation polymers.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-31", "question": "A deficiency of vitamin C causes:", "options": ["Beri-beri", "Night blindness", "Scurvy (bleeding gums)", "Rickets"], "answer": 2, "explanation": "Vitamin C (ascorbic acid) deficiency causes scurvy, with bleeding gums. Rickets is vitamin D, beri-beri vitamin B₁ and night blindness vitamin A.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-32", "question": "Almost all enzymes, the biological catalysts, are:", "options": ["Globular proteins", "Nucleic acids", "Lipids", "Carbohydrates"], "answer": 0, "explanation": "Enzymes are mostly globular proteins, highly specific for particular reactions and substrates.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-33", "question": "Amino acids in a protein are joined by:", "options": ["Phosphodiester linkages", "Peptide (amide) bonds, –CO–NH–", "Ester linkages", "Glycosidic linkages"], "answer": 1, "explanation": "The –COOH of one amino acid condenses with the –NH₂ of the next, eliminating water and forming a peptide bond. Glycosidic links join sugars; phosphodiester links join nucleotides.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-34", "question": "Aniline reacts with bromine water at room temperature to give:", "options": ["4-Bromoaniline only", "3-Bromoaniline", "A mixture of 2- and 4-bromoaniline", "2,4,6-Tribromoaniline as a white precipitate"], "answer": 3, "explanation": "–NH₂ strongly activates the ring, so all ortho and para positions are brominated at once, giving a white precipitate of 2,4,6-tribromoaniline. Monobromination needs the –NH₂ to be acetylated first.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-35", "question": "Nitrobenzene is preferably reduced to aniline with scrap iron and HCl because:", "options": ["The reaction needs no heating at all", "It gives N-phenylhydroxylamine as the main product", "Iron is a stronger reducing agent than tin", "FeCl₂ formed is hydrolysed, releasing HCl, so only a small amount of acid is needed"], "answer": 3, "explanation": "FeCl₂ formed hydrolyses to regenerate HCl, so the reaction needs only a small amount of acid to start (NCERT). Iron is also cheap.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-36", "question": "Benzenediazonium chloride is warmed with CuCl/HCl. The product and name of the reaction are:", "options": ["Phenol; Sandmeyer reaction", "Chlorobenzene; Gattermann–Koch reaction", "Chlorobenzene; Sandmeyer reaction", "Benzene; Balz–Schiemann reaction"], "answer": 2, "explanation": "Cu(I) salts replace –N₂⁺ with Cl, Br or CN: this is the Sandmeyer reaction. (With copper powder and HCl it is the Gattermann reaction.)", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-37", "question": "In aqueous solution near neutral pH, α-amino acids exist mainly as:", "options": ["Neutral molecules H₂N–CHR–COOH", "Cations H₃N⁺–CHR–COOH only", "Dipolar ions (zwitterions), H₃N⁺–CHR–COO⁻", "Anions H₂N–CHR–COO⁻ only"], "answer": 2, "explanation": "The acidic –COOH protonates the basic –NH₂ within the same molecule, giving a zwitterion. This explains their high melting points, water solubility and amphoteric behaviour.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-38", "question": "Lactose (milk sugar) is made up of:", "options": ["α-D-Glucose and β-D-fructose joined by a C1–C2 link", "Two β-D-glucose units joined by a C1–C6 link", "β-D-Galactose and β-D-glucose joined by a C1–C4 link", "Two α-D-glucose units joined by a C1–C4 link"], "answer": 2, "explanation": "Lactose = β-D-galactose (C-1) linked to C-4 of β-D-glucose. Two α-D-glucose units (C1–C4) is maltose; glucose + fructose (C1–C2) is sucrose.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "chem-amines-biomolecules-39", "question": "The monomer of neoprene is:", "options": ["2-Chlorobuta-1,3-diene (chloroprene)", "Vinyl chloride", "Buta-1,3-diene", "2-Methylbuta-1,3-diene"], "answer": 0, "explanation": "Neoprene, a synthetic rubber resistant to oils, is made by free-radical polymerisation of chloroprene. 2-Methylbuta-1,3-diene (isoprene) is the monomer of natural rubber.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-40", "question": "Which of the following is the strongest base?", "options": ["4-Methoxyaniline", "4-Chloroaniline", "4-Nitroaniline", "Aniline"], "answer": 0, "explanation": "–OCH₃ at the para position pushes electron density onto the ring and nitrogen (+R), raising basicity above aniline. –Cl (−I) and especially –NO₂ (−I, −R) pull the lone pair away and lower basicity.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-41", "question": "The product of a secondary amine with benzenesulphonyl chloride (Hinsberg's reagent) is:", "options": ["An isocyanide", "A diazonium salt", "Soluble in alkali, because it has an acidic N–H", "Insoluble in alkali, because it has no hydrogen on nitrogen"], "answer": 3, "explanation": "R₂NH gives C₆H₅SO₂NR₂, which has no N–H, so it is not acidic and does not dissolve in alkali. Primary amines give C₆H₅SO₂NHR, which dissolves in alkali because of the acidic N–H.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-42", "question": "When an alkyl halide is heated with ammonia, the primary amine can be made the main product by:", "options": ["Using a large excess of ammonia", "Carrying out the reaction in the gas phase", "Using a large excess of the alkyl halide", "Adding a strong acid"], "answer": 0, "explanation": "Ammonolysis gives a mixture because the amine formed is itself a nucleophile and is alkylated further. A large excess of NH₃ makes it far more likely that the halide meets NH₃ rather than the amine.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-43", "question": "Which sequence converts an alkyl halide R–X into an amine with ONE MORE carbon atom?", "options": ["R–X + NH₃, then Hoffmann bromamide reaction", "R–X + KCN, then reduction with LiAlH₄", "R–X + NaNO₂, then reduction", "R–X + potassium phthalimide, then hydrolysis"], "answer": 1, "explanation": "R–X → R–CN → R–CH₂NH₂ adds the nitrile carbon. Gabriel synthesis and ammonolysis keep the carbon count, and the Hoffmann bromamide reaction removes one carbon.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-44", "question": "Glycogen, the storage polysaccharide of animals, is structurally most similar to:", "options": ["Chitin", "Amylose, being completely unbranched", "Cellulose, but with α-links", "Amylopectin, but even more highly branched"], "answer": 3, "explanation": "Glycogen, stored in liver, muscles and brain, is a branched polymer of α-D-glucose like amylopectin (α-1,4 chains with α-1,6 branches) but with more frequent branching.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "chem-amines-biomolecules-45", "question": "In a nucleic acid chain, successive nucleotides are joined by:", "options": ["Phosphodiester linkages between C-5′ of one sugar and C-3′ of the next", "Glycosidic linkages between C-1′ of two sugars", "Hydrogen bonds between bases", "Peptide bonds"], "answer": 0, "explanation": "The phosphate links the 5′-OH of one pentose to the 3′-OH of the next. The base is joined to C-1′ by a glycosidic (N-glycosidic) bond, and the hydrogen bonds between bases hold the two strands of DNA together.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "chem-amines-biomolecules-46", "question": "Which statement correctly describes the α-helix in proteins?", "options": ["It is formed by hydrogen bonds between neighbouring parallel chains", "It is a left-handed helix stabilised by disulphide bonds", "It is the primary structure of the protein", "It is a right-handed helix in which each N–H is hydrogen-bonded to a C=O of an adjacent turn of the same chain"], "answer": 3, "explanation": "In the α-helix (a secondary structure) one chain twists into a right-handed screw held by intramolecular N–H···O=C hydrogen bonds. Hydrogen bonding between side-by-side chains is the β-pleated sheet.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "chem-amines-biomolecules-47", "question": "High-density polythene is made by polymerising ethene:", "options": ["By condensation with ethylene glycol", "At 1000–2000 atm and 350–570 K with a trace of peroxide", "By emulsion polymerisation with sulphur", "With a Ziegler–Natta catalyst (Al(C₂H₅)₃ + TiCl₄) at 333–343 K and 6–7 atm"], "answer": 3, "explanation": "The Ziegler–Natta catalyst gives linear chains that pack closely: HDPE, which is denser, harder and tougher. High pressure with a free-radical initiator gives branched low-density polythene.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-48", "question": "Arenediazonium salts are much more stable than alkanediazonium salts because:", "options": ["Arenediazonium salts are always made in the dark", "The positive charge is spread over the benzene ring by resonance", "Nitrogen is sp³ hybridised in arenediazonium ions", "The aryl group has a +I effect"], "answer": 1, "explanation": "Delocalisation of the –N₂⁺ charge into the ring stabilises ArN₂⁺, which keeps for a short time in cold (273–278 K) solution. Alkanediazonium ions lose N₂ at once even in the cold.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-49", "question": "How many of the following vitamin–deficiency pairs are correct? (A) Vitamin D – rickets. (B) Vitamin K – increased blood clotting time. (C) Vitamin B₆ – convulsions. (D) Vitamin E – night blindness.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct (NCERT table). D is wrong: night blindness is due to lack of vitamin A; vitamin E deficiency increases the fragility of red blood cells and causes muscular weakness.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-amines-biomolecules-50", "question": "Assertion (A): Acetylation of aniline reduces the activating effect of the –NH₂ group on the benzene ring. Reason (R): In acetanilide, the nitrogen lone pair is also delocalised onto the oxygen of the acetyl group, so less of it is available to the ring.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Amide resonance competes with the ring for the lone pair, so –NHCOCH₃ is only moderately activating. This is why acetanilide can be monobrominated or nitrated cleanly.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-51", "question": "Match the reaction (Column I) with the conversion it achieves (Column II). (a) Sandmeyer, (b) Gattermann, (c) Balz–Schiemann, (d) Coupling. (1) ArN₂⁺BF₄⁻ heated → ArF, (2) ArN₂⁺ with CuCl/HCl → ArCl, (3) ArN₂⁺ with Cu powder/HCl → ArCl, (4) ArN₂⁺ with aniline → p-aminoazobenzene.", "options": ["a-2, b-3, c-1, d-4", "a-1, b-3, c-2, d-4", "a-2, b-3, c-4, d-1", "a-3, b-2, c-1, d-4"], "answer": 0, "explanation": "Sandmeyer uses Cu(I) salts (2) and Gattermann uses copper powder with HX (3). Heating the diazonium fluoroborate gives aryl fluorides (1). Coupling with aniline gives the yellow azo dye p-aminoazobenzene (4).", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-52", "question": "Aniline is treated in turn with (i) acetic anhydride, (ii) Br₂ in CH₃COOH, and (iii) aqueous acid with heating. The main final product is:", "options": ["4-Bromoaniline", "2,4,6-Tribromoaniline", "3-Bromoaniline", "4-Bromoacetanilide"], "answer": 0, "explanation": "(i) gives acetanilide, whose milder activation allows monobromination; (ii) gives mainly 4-bromoacetanilide (para, because ortho is hindered); (iii) hydrolysis removes the acetyl group to give 4-bromoaniline.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-53", "question": "How many of the following statements about glucose are correct? (A) It is oxidised by bromine water to saccharic acid. (B) It is oxidised by nitric acid to saccharic acid. (C) With acetic anhydride it forms a tetraacetate. (D) Glucose and mannose differ only in the configuration at C-2.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "B and D are correct. A is wrong: bromine water oxidises only the CHO group, giving gluconic acid. C is wrong: glucose forms a pentaacetate, showing five –OH groups.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-amines-biomolecules-54", "question": "18 g of glucose (molar mass 180 g/mol) is completely acetylated with acetic anhydride. The mass of glucose pentaacetate formed is:", "options": ["27.0 g", "39.0 g", "34.8 g", "22.2 g"], "answer": 1, "explanation": "Each –OH → –OCOCH₃ adds 42 g/mol (COCH₃ replaces H), so the pentaacetate is 180 + 5 × 42 = 390 g/mol. 0.1 mol of glucose gives 0.1 × 390 = 39.0 g.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-amines-biomolecules-55", "question": "0.59 g of a monoacidic amine needs 10 mL of 1 M HCl for neutralisation. Its product with benzenesulphonyl chloride is insoluble in alkali. The amine is:", "options": ["Propan-1-amine", "Propan-2-amine", "N,N-Dimethylmethanamine", "N-Methylethanamine"], "answer": 3, "explanation": "Moles = 0.010, so M = 59, i.e. C₃H₉N. A Hinsberg product insoluble in alkali (but formed) means a secondary amine: CH₃NHC₂H₅. The tertiary amine does not react with the reagent at all.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-amines-biomolecules-56", "question": "The molar mass of the linear pentapeptide formed from five glycine molecules (molar mass 75 g/mol) is:", "options": ["357 g/mol", "375 g/mol", "303 g/mol", "285 g/mol"], "answer": 2, "explanation": "Five residues are joined by four peptide bonds, each releasing one water: 5 × 75 − 4 × 18 = 375 − 72 = 303 g/mol. 285 g/mol wrongly subtracts five waters.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-57", "question": "How many of the following statements about polymers are correct? (A) Teflon is made from tetrafluoroethene. (B) Glyptal is a polymer of ethane-1,2-diol and phthalic acid. (C) Melamine–formaldehyde polymer is used for unbreakable crockery. (D) Novolac, on heating with formaldehyde, forms Bakelite.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct (NCERT). Novolac is the linear product from phenol and HCHO; further heating with HCHO cross-links it into the thermosetting Bakelite.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-amines-biomolecules-58", "question": "Each of the following amines is treated with NaNO₂/HCl at 273–278 K and then with alkaline 2-naphthol. Which does NOT give an azo dye?", "options": ["Benzylamine", "Aniline", "4-Methylaniline", "4-Chloroaniline"], "answer": 0, "explanation": "In benzylamine (C₆H₅CH₂NH₂) the –NH₂ is on an alkyl carbon, so its diazonium ion is not resonance-stabilised and loses N₂ at once (giving mainly the alcohol). The arylamines form stable diazonium salts that couple to give orange-red dyes.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-amines-biomolecules-59", "question": "A double-stranded DNA segment of 1000 base pairs contains 300 adenine bases. The total number of hydrogen bonds between its two strands is:", "options": ["3000", "2300", "2000", "2700"], "answer": 3, "explanation": "300 A pair with 300 T, giving 300 A=T pairs (2 H-bonds each) = 600. The other 700 pairs are G≡C (3 each) = 2100. Total 2700.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-amines-biomolecules-60", "question": "In the gas phase, where solvation plays no part, the correct order of basic strength is:", "options": ["(CH₃)₃N > (CH₃)₂NH > CH₃NH₂ > NH₃", "CH₃NH₂ > (CH₃)₂NH > (CH₃)₃N > NH₃", "(CH₃)₂NH > CH₃NH₂ > (CH₃)₃N > NH₃", "NH₃ > CH₃NH₂ > (CH₃)₂NH > (CH₃)₃N"], "answer": 0, "explanation": "With no solvation, only the +I effect of the alkyl groups matters, so basicity rises steadily 3° > 2° > 1° > NH₃. The order (CH₃)₂NH > CH₃NH₂ > (CH₃)₃N holds in water, where H-bonded solvation of the cation also counts.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-amines-biomolecules-61", "question": "For glycine, pKa₁ (–COOH) = 2.34 and pKa₂ (–NH₃⁺) = 9.60. Its isoelectric point is:", "options": ["5.97", "7.00", "11.94", "3.63"], "answer": 0, "explanation": "At the isoelectric point the zwitterion dominates and the net charge is zero: pI = (pKa₁ + pKa₂)/2 = (2.34 + 9.60)/2 = 5.97. Taking pH 7 (neutral water) as the pI is the trap; 11.94 is the sum without halving.", "difficulty": "moderate", "source": "JEE Main"},
  {"id":"chem-amines-biomolecules-62","question":"Gabriel phthalimide synthesis cannot be used to prepare aniline because:","options":["Aniline is too basic to be released from the imide","Aryl halides do not undergo SN2 substitution with the phthalimide anion","Phthalimide does not react with KOH","Aniline reacts with phthalic acid during hydrolysis"],"answer":1,"explanation":"The key step is SN2 attack of the phthalimide anion on an alkyl halide; aryl halides do not undergo this (the C–X bond has partial double-bond character and backside attack is blocked by the ring). So Gabriel synthesis gives only primary aliphatic amines.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-63","question":"The number of stereocentres (chiral carbon atoms) in the open-chain form of D-fructose is:","options":["4","5","3","2"],"answer":2,"explanation":"Open-chain fructose is CH₂OH–CO–CHOH–CHOH–CHOH–CH₂OH; C3, C4 and C5 are stereocentres, while C1 and C6 (CH₂OH) and C2 (C=O) are not. Glucose, an aldohexose, has four (C2–C5) in its open form, which is the number students carry over.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-64","question":"A primary aliphatic amine is warmed with CS₂, and the product is heated with HgCl₂. A pungent smell of mustard oil develops. The compound responsible is:","options":["An alkyl isocyanide, R–NC","An alkyl thiocyanate, R–S–C≡N","A dithiocarbamic acid, R–NH–CS–SH","An alkyl isothiocyanate, R–N=C=S"],"answer":3,"explanation":"RNH₂ + CS₂ gives the N-alkyldithiocarbamic acid, which HgCl₂ decomposes (removing H₂S as HgS) to the isothiocyanate R–N=C=S, the 'mustard oil'. Secondary and tertiary amines do not give it. The isocyanide smell comes from the carbylamine test with CHCl₃/KOH.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-65","question":"Benzenediazonium chloride is warmed with aqueous KI. The product is:","options":["Iodobenzene, formed without any copper catalyst","Phenol","Iodobenzene, but only in the presence of CuI","p-Iodoaniline"],"answer":0,"explanation":"Iodide is a good enough electron donor to react with the diazonium ion directly, so ArN₂⁺ + I⁻ → ArI + N₂ needs no copper salt. Chloro and bromo compounds, by contrast, need Cu(I) (Sandmeyer) or Cu powder (Gattermann).","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-66","question":"Acetamide is a very weak base. When it is protonated by a strong acid, the proton attaches mainly to:","options":["Nitrogen, because N carries the lone pair","Oxygen, because the resulting cation is resonance-stabilised over O, C and N","The methyl carbon","The carbonyl carbon"],"answer":1,"explanation":"The nitrogen lone pair is delocalised into the C=O group (amide resonance), so N is not basic. Protonation at O gives a cation whose positive charge is shared with N (H₂N⁺=C(OH)CH₃), whereas protonation at N would destroy the amide resonance.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-67","question":"Which sequence converts benzene into m-bromoaniline?","options":["Nitration → reduction (Sn/HCl) → bromination (Br₂ water)","Bromination (Br₂/FeBr₃) → nitration → reduction (Sn/HCl)","Nitration → bromination (Br₂/FeBr₃) → reduction (Sn/HCl)","Nitration → reduction → acetylation → bromination → hydrolysis"],"answer":2,"explanation":"–NO₂ is meta-directing, so bromination after nitration puts Br meta, and reduction then gives m-bromoaniline. Brominating first (o/p-directing Br) gives o/p products; brominating aniline with bromine water gives 2,4,6-tribromoaniline; the acetanilide route gives the para isomer.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-68","question":"4.65 g of aniline (molar mass 93) is diazotised completely at 273–278 K, and the solution is then warmed until no more gas is evolved. The volume of nitrogen at STP is:","options":["2.24 L","3.36 L","0.56 L","1.12 L"],"answer":3,"explanation":"0.050 mol aniline gives 0.050 mol C₆H₅N₂⁺Cl⁻, which on warming in water gives phenol + N₂ + HCl, i.e. 0.050 mol N₂ = 1.12 L. Note that both nitrogen atoms of N₂ come from aniline and nitrite together, so there is one N₂ per diazonium ion, not two.","difficulty":"hard","source":"JEE Main"},
  {"id": "chem-amines-biomolecules-69", "question": "A mixture of lysine (pI 9.7), glycine (pI 6.0) and glutamic acid (pI 3.2) is subjected to electrophoresis in a buffer of pH 6.0. Which statement is correct?", "options": ["All three move towards the anode", "Lysine moves towards the cathode, glutamic acid towards the anode, and glycine hardly moves", "Lysine moves towards the anode and glutamic acid towards the cathode", "None of them moves, since all are zwitterions"], "answer": 1, "explanation": "At a pH below its pI an amino acid carries net positive charge (lysine at pH 6 → cation → cathode); above its pI it carries net negative charge (glutamic acid → anion → anode); at its pI (glycine) the net charge is zero and it stays near the origin.", "difficulty": "hard", "source": "JEE Main"},
  {"id":"chem-amines-biomolecules-70","question":"Natural rubber and gutta-percha are both polyisoprene. The difference between them is that:","options":["Natural rubber is cis-1,4-polyisoprene, while gutta-percha is trans-1,4-polyisoprene","Gutta-percha is cross-linked with sulphur, while natural rubber is not","Natural rubber is trans-1,4-polyisoprene, while gutta-percha is cis","Natural rubber is a condensation polymer, while gutta-percha is an addition polymer"],"answer":0,"explanation":"In natural rubber the chains have the cis configuration at each double bond, which makes them coiled and unable to pack closely, giving elasticity. The all-trans chains of gutta-percha pack regularly, making it hard and non-elastic. Both are addition polymers, and sulphur cross-linking is vulcanisation.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-71","question":"Which of the following is the strongest base in water?","options":["Aniline","N,N-Dimethyl-o-toluidine","N,N-Dimethylaniline","o-Toluidine"],"answer":1,"explanation":"In N,N-dimethyl-o-toluidine the ortho CH₃ clashes with the N(CH₃)₂ group and twists it out of the ring plane, so the nitrogen lone pair can no longer be delocalised into the ring (steric inhibition of resonance) and is more available (pKa of conjugate acid ≈ 5.9 vs 5.1). For the primary amine the opposite holds: o-toluidine is weaker than aniline because of the ortho effect on solvation of the anilinium ion.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-72","question":"Propan-1-amine is treated with NaNO₂ and dilute HCl at room temperature. The organic products are:","options":["Propanenitrile","Propan-1-ol only","A mixture containing propan-1-ol, propan-2-ol and propene (with some 1-chloropropane)","Propane-1-diazonium chloride, stable at room temperature"],"answer":2,"explanation":"Aliphatic diazonium ions lose N₂ at once, giving the primary propyl cation (or a cation-like species) that is trapped by water, rearranges by a 1,2-hydride shift to the isopropyl cation, loses H⁺ to give propene, or is captured by Cl⁻. N₂ is evolved quantitatively, but the alcohol yield is poor — the reaction is used for detecting, not making.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-73","question":"Match the reduction of nitrobenzene (Column I) with the main product (Column II). (a) Sn/HCl, (b) Zn/NH₄Cl (neutral), (c) Zn/NaOH, (d) LiAlH₄. (1) Hydrazobenzene, (2) Azobenzene, (3) Aniline, (4) N-Phenylhydroxylamine.","options":["a-3, b-1, c-4, d-2","a-3, b-4, c-2, d-1","a-4, b-3, c-1, d-2","a-3, b-4, c-1, d-2"],"answer":3,"explanation":"In acid the reduction goes all the way to C₆H₅NH₂. In neutral medium it stops at C₆H₅NHOH. In alkaline medium the nitroso and hydroxylamine intermediates condense, and with Zn/NaOH the azoxy/azo compound is reduced further to hydrazobenzene, C₆H₅NH–NHC₆H₅. LiAlH₄ gives azobenzene, C₆H₅N=NC₆H₅.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-74","question":"Aniline is converted in turn by (i) NaNO₂/HCl at 273–278 K, (ii) CuCN/KCN, (iii) H₂/Ni (or LiAlH₄) and (iv) NaNO₂/HCl at room temperature. The final product is:","options":["Benzyl alcohol","Phenol","Benzonitrile","Benzenediazonium chloride"],"answer":0,"explanation":"Diazotisation and Sandmeyer give C₆H₅CN; reduction gives benzylamine, C₆H₅CH₂NH₂, which is an aliphatic primary amine (NH₂ on an sp³ carbon). Its diazonium ion is unstable, losing N₂ at once to give benzyl alcohol. Treating benzylamine like aniline (a stable diazonium salt) is the trap.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-amines-biomolecules-75", "question": "How many of the following statements about proteins are correct? (A) The α-helix is stabilised by hydrogen bonds between the C=O of one residue and the N–H of the residue four places along the same chain. (B) In a β-pleated sheet, neighbouring chains are held side by side by intermolecular hydrogen bonds. (C) Quaternary structure exists only in proteins made of two or more polypeptide subunits. (D) Fibrous proteins such as keratin and myosin are generally soluble in water.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct. D is wrong: fibrous proteins have long, parallel chains held together by hydrogen and disulphide bonds and are generally insoluble in water; it is globular proteins (e.g. insulin, albumins) that are water-soluble.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-amines-biomolecules-76", "question": "α-D-Glucopyranose has [α]D = +112° and β-D-glucopyranose has [α]D = +18.7°. At equilibrium in water the specific rotation is +52.7°. Neglecting the open-chain form, the percentage of the α anomer at equilibrium is about:", "options": ["64%", "36%", "50%", "47%"], "answer": 1, "explanation": "If x is the fraction of α: 112x + 18.7(1 − x) = 52.7, so 93.3x = 34.0 and x = 0.364, i.e. about 36% α and 64% β. The β anomer dominates because all its substituents, including the C1–OH, are equatorial. Answering 64% swaps the two anomers.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-amines-biomolecules-77", "question": "How many of the following statements about polysaccharides are correct? (A) Amylose is an unbranched chain of α-D-glucose units joined by C1–C4 glycosidic links. (B) Amylopectin has branches formed by C1–C6 α-glycosidic links. (C) Cellulose is a linear polymer of β-D-glucose joined by C1–C4 links. (D) Glycogen is more highly branched than amylopectin.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The α (starch) versus β (cellulose) linkage decides digestibility by humans, and glycogen, the animal storage form, has branches more often (every 8–12 units) than amylopectin (every 20–25 units).", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-amines-biomolecules-78", "question": "How many of the following statements about nucleic acids are correct? (A) A nucleoside contains a base and a sugar; a nucleotide also contains a phosphate group. (B) The sugar in DNA is 2-deoxy-D-ribose. (C) Cytosine is found only in DNA, not in RNA. (D) An adenine–thymine pair is held by three hydrogen bonds.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A and B are correct. C is wrong: cytosine occurs in both DNA and RNA; the base found only in DNA is thymine (only in RNA: uracil). D is wrong: A=T has two hydrogen bonds, G≡C has three.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-amines-biomolecules-79","question":"A sample of nylon-6,6 has an average molar mass of 22 600 g mol⁻¹. The number of adipic acid molecules that went into one average chain is about (C = 12, H = 1, N = 14, O = 16):","options":["155","200","100","50"],"answer":2,"explanation":"The repeat unit –NH(CH₂)₆NH–CO(CH₂)₄CO– is C₁₂H₂₂N₂O₂ = 226 g mol⁻¹ and contains one diamine and one adipic acid residue (two waters lost). 22 600/226 = 100 repeat units, so about 100 adipic acid molecules. Dividing by the molar mass of adipic acid (146) gives 155, the trap.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-amines-biomolecules-80", "question": "The correct decreasing order of basic strength (in water) of the toluidines and aniline is:", "options": ["o-Toluidine > m-toluidine > p-toluidine > aniline", "Aniline > p-toluidine > m-toluidine > o-toluidine", "m-Toluidine > p-toluidine > o-toluidine > aniline", "p-Toluidine > m-toluidine > aniline > o-toluidine"], "answer": 3, "explanation": "pKb ≈ 8.9 (para), 9.3 (meta), 9.4 (aniline), 9.6 (ortho). The para CH₃ releases electrons by hyperconjugation and +I; meta acts only by a weak +I. The ortho isomer is the weakest because the CH₃ hinders solvation of the anilinium ion (ortho effect), so it falls below even aniline.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-amines-biomolecules-81", "question": "How many of the following statements about the reactions of amines with nitrous acid (NaNO₂ + HCl, cold) are correct? (A) Secondary amines give yellow, oily N-nitrosamines. (B) Tertiary aliphatic amines simply form soluble nitrite salts. (C) N,N-Dimethylaniline gives p-nitroso-N,N-dimethylaniline. (D) Primary aromatic amines at 273–278 K immediately evolve N₂ quantitatively.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct; the strongly activated ring of N,N-dimethylaniline undergoes electrophilic attack by NO⁺ at the para position. D is wrong: in the cold, primary aromatic amines give stable diazonium salts; N₂ is evolved quickly only from primary aliphatic amines (or on warming the diazonium salt).", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-amines-biomolecules-82", "question": "(S)-2-Methylbutanamide, CH₃CH₂CH(CH₃)CONH₂, is treated with Br₂ and aqueous NaOH. The amine obtained is:", "options": ["(S)-Butan-2-amine", "(R)-Butan-2-amine", "Racemic butan-2-amine", "(S)-2-Methylbutan-1-amine"], "answer": 0, "explanation": "In the Hofmann bromamide rearrangement the alkyl group migrates from carbon to nitrogen with complete retention of configuration. The chiral carbon keeps its spatial arrangement, and since NH₂ takes the place of CONH₂ as the highest-priority group, the descriptor stays S. The product has one carbon fewer, so 2-methylbutan-1-amine is wrong.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "chem-amines-biomolecules-83", "question": "In the Hofmann bromamide degradation RCONH₂ → RNH₂, the numbers of moles of Br₂ and NaOH consumed per mole of amide are:", "options": ["1 mol Br₂ and 2 mol NaOH", "1 mol Br₂ and 4 mol NaOH", "2 mol Br₂ and 4 mol NaOH", "1 mol Br₂ and 3 mol NaOH"], "answer": 1, "explanation": "RCONH₂ + Br₂ + 4NaOH → RNH₂ + Na₂CO₃ + 2NaBr + 2H₂O. NaOH is needed to deprotonate the amide twice (forming the N-bromoamide anion), and the isocyanate is hydrolysed to the amine and CO₂, which is trapped as Na₂CO₃ (2 more NaOH).", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-amines-biomolecules-84","question":"The correct decreasing order of basic strength (in water) is:","options":["Aniline > N-methylaniline > benzylamine > p-nitroaniline","N-Methylaniline > benzylamine > aniline > p-nitroaniline","Benzylamine > N-methylaniline > aniline > p-nitroaniline","Benzylamine > aniline > p-nitroaniline > N-methylaniline"],"answer":2,"explanation":"In benzylamine the NH₂ is on an sp³ carbon, so its lone pair is not delocalised (pKb ≈ 4.7). N-Methylaniline is slightly more basic than aniline (+I of CH₃; pKb ≈ 9.2 vs 9.4). In p-nitroaniline the lone pair is pulled into the nitro group by resonance (pKb ≈ 13).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-85","question":"One mole of glucose (treated as its open-chain form) is oxidised with excess periodic acid. The moles of HIO₄ consumed and the products are:","options":["5 mol HIO₄; 4 HCOOH + 1 HCHO + 1 CO₂","4 mol HIO₄; 4 HCOOH + 2 HCHO","6 mol HIO₄; 6 HCOOH","5 mol HIO₄; 5 HCOOH + 1 HCHO"],"answer":3,"explanation":"Each of the five C–C bonds in OHC–(CHOH)₄–CH₂OH joins carbons bearing O, so 5 HIO₄ are used. The CHO and the four CHOH carbons each end up as HCOOH, and the terminal CH₂OH becomes HCHO. This 5 : 1 product ratio was used as evidence for the straight-chain aldohexose structure.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-86","question":"Which of the following is a secondary (2°) amine?","options":["CH₃–NH–C₂H₅","(CH₃)₂CH–NH₂","(CH₃)₃C–NH₂","(CH₃)₃N"],"answer":0,"explanation":"The degree of an amine is the number of carbon groups bonded to nitrogen, not the degree of the carbon carrying N. CH₃NHC₂H₅ (N-methylethanamine) has two alkyl groups on N, so it is 2°. Isopropylamine and tert-butylamine are both 1° amines (one carbon on N) and trimethylamine is 3°.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-87","question":"The pentose sugar present in the nucleotides of DNA is:","options":["D-Arabinose","D-Ribose","D-Fructose","2-Deoxy-D-ribose"],"answer":3,"explanation":"DNA (deoxyribonucleic acid) contains β-D-2-deoxyribose, which lacks the –OH group at C-2′. RNA contains β-D-ribose. The missing 2′-OH makes DNA more resistant to alkaline hydrolysis than RNA.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-88","question":"Benzylamine (C₆H₅CH₂NH₂) and aniline (C₆H₅NH₂) can be distinguished by:","options":["Benzenesulphonyl chloride followed by aqueous KOH","CHCl₃ and alcoholic KOH","NaNO₂/HCl at 273–278 K followed by alkaline β-naphthol","Dilute hydrochloric acid"],"answer":2,"explanation":"Both are primary amines, so both give the carbylamine test, both give alkali-soluble Hinsberg sulphonamides and both dissolve in dilute HCl. Only aniline forms a stable arenediazonium salt at 0–5 °C that couples with β-naphthol to give an orange-red azo dye. Benzylamine is an aliphatic-type amine: its diazonium ion decomposes at once, giving N₂ and benzyl alcohol, so no dye forms.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-89","question":"Glyptal, used in paints and lacquers, is a condensation polymer of:","options":["Ethane-1,2-diol and terephthalic acid","Ethane-1,2-diol and benzene-1,2-dicarboxylic (phthalic) acid","Phenol and methanal","Hexamethylenediamine and adipic acid"],"answer":1,"explanation":"Glyptal is a polyester made from ethylene glycol and phthalic acid (or phthalic anhydride). Ethylene glycol with terephthalic acid gives Terylene (Dacron), phenol with methanal gives Bakelite, and hexamethylenediamine with adipic acid gives nylon-6,6.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-90","question":"A solution of egg albumin gives a violet colour when treated with dilute NaOH and a drop of dilute CuSO₄ solution. This test (and the structural feature it detects) is:","options":["Biuret test — two or more peptide bonds","Molisch's test — a carbohydrate unit","Xanthoproteic test — an aromatic ring","Ninhydrin test — a free α-amino acid only"],"answer":0,"explanation":"In the biuret test Cu²⁺ in alkaline solution forms a violet complex with the nitrogen atoms of –CO–NH– (peptide) linkages, so any peptide with at least two peptide bonds responds. The xanthoproteic test (conc. HNO₃, yellow) detects aromatic side chains, and Molisch's test (α-naphthol/conc. H₂SO₄, violet ring) detects carbohydrates.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-91","question":"Which disaccharide is made of two α-D-glucose units joined by an α(1→4) glycosidic link and is a reducing sugar?","options":["Cellobiose","Sucrose","Lactose","Maltose"],"answer":3,"explanation":"Maltose = α-D-glucose C-1 → C-4 of a second D-glucose; the second unit keeps a free hemiacetal carbon, so maltose reduces Fehling's and Tollens' reagents. Cellobiose has the same units but a β(1→4) link, lactose contains galactose, and sucrose (glucose + fructose, C1–C2 link) is non-reducing.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-92","question":"The thyroid hormone thyroxine is biosynthesised from which amino acid?","options":["Histidine","Tryptophan","Tyrosine","Glycine"],"answer":2,"explanation":"Thyroxine (T₄) is an iodinated derivative of tyrosine: two iodinated tyrosine residues are coupled in thyroglobulin to form the diphenyl ether skeleton carrying four iodine atoms. Tryptophan is the precursor of serotonin and histidine of histamine. Iodine deficiency therefore causes goitre.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-amines-biomolecules-93","question":"Bromoethane is heated with AgCN, and the product is reduced with Na/C₂H₅OH. The amine obtained is:","options":["Propan-1-amine, CH₃CH₂CH₂NH₂","N-Methylethanamine, CH₃CH₂NHCH₃","Ethanamine, CH₃CH₂NH₂","N,N-Dimethylmethanamine, (CH₃)₃N"],"answer":1,"explanation":"AgCN is largely covalent, so attack occurs through nitrogen and ethyl isocyanide, C₂H₅–N≡C, is formed. Reduction converts the isocyanide carbon into a methyl group on nitrogen: C₂H₅NC + 4[H] → C₂H₅NHCH₃, a secondary amine. With KCN the nitrile C₂H₅CN would form instead, and its reduction gives propan-1-amine.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-94","question":"The correct decreasing order of basic strength in water is:","options":["Piperidine > pyridine > aniline > pyrrole","Pyridine > piperidine > aniline > pyrrole","Piperidine > aniline > pyridine > pyrrole","Pyrrole > piperidine > pyridine > aniline"],"answer":0,"explanation":"Piperidine is a saturated 2° amine with an sp³ lone pair (pKb ≈ 2.9). Pyridine's lone pair is in an sp² orbital with more s-character and is held more tightly (pKb ≈ 8.8), but it is not delocalised, so pyridine is slightly more basic than aniline (pKb ≈ 9.4), whose lone pair is delocalised into the ring. In pyrrole the lone pair is part of the aromatic sextet, making it practically non-basic.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-95","question":"Coupling of benzenediazonium chloride with phenol is carried out at pH ≈ 9–10, whereas coupling with aniline is carried out at pH ≈ 4–5. The best explanation is:","options":["Phenol is a stronger base than aniline and must be deprotonated to dissolve","Diazonium ions are electrophiles only in strongly alkaline solution","Aniline reacts with the diazonium ion through nitrogen only in alkaline solution, so acid is needed to direct attack to carbon","Phenol must be present as the strongly activating phenoxide ion, while for aniline too low a pH protonates the –NH₂ group and too high a pH converts ArN₂⁺ into an unreactive diazohydroxide/diazotate"],"answer":3,"explanation":"ArN₂⁺ is a weak electrophile and needs a strongly activated ring. In mild alkali phenol becomes C₆H₅O⁻, a far stronger activator. For aniline a mildly acidic medium is a compromise: strong acid would give the deactivated anilinium ion, while alkali would destroy the diazonium ion as Ar–N=N–OH/Ar–N=N–O⁻. Very strong alkali is avoided with phenol for the same reason.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-96","question":"N,N,N-Trimethylbutan-2-aminium hydroxide, CH₃CH₂CH(CH₃)N⁺(CH₃)₃ OH⁻, is heated. The major alkene formed is:","options":["(Z)-But-2-ene","(E)-But-2-ene","But-1-ene","2-Methylpropene"],"answer":2,"explanation":"Hofmann elimination is an E2 reaction with a poor, bulky leaving group (NMe₃). The carbanion-like transition state makes the more acidic, less hindered β-hydrogens of the CH₃ group react faster than those of the CH₂ group. Hence the less substituted alkene, but-1-ene, is the major product (Hofmann rule), opposite to the Saytzeff product of dehydrohalogenation.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-97","question":"A tripeptide gives glycine, alanine and phenylalanine on complete hydrolysis. Partial hydrolysis gives only the dipeptides Gly-Ala and Phe-Gly. The sequence of the tripeptide (N-terminus → C-terminus) is:","options":["Gly-Ala-Phe","Phe-Gly-Ala","Ala-Gly-Phe","Phe-Ala-Gly"],"answer":1,"explanation":"Gly-Ala shows Gly is bonded to the N-atom side of Ala, and Phe-Gly shows Phe precedes Gly. Overlapping the fragments at Gly gives Phe-Gly-Ala. Gly-Ala-Phe would have produced Ala-Phe instead of Phe-Gly on partial hydrolysis.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-98","question":"Sulphanilic acid (4-aminobenzenesulphonic acid) has a very high melting point, is insoluble in organic solvents, dissolves in aqueous NaOH but not in dilute HCl. This is best explained by:","options":["Its existence as the dipolar ion H₃N⁺–C₆H₄–SO₃⁻, whose –NH₃⁺ can lose H⁺ to base while the weakly basic –SO₃⁻ is not protonated by dilute acid","Strong intramolecular hydrogen bonding between –NH₂ and –SO₃H","The –NH₂ group being more basic than in aniline","Dimerisation through the –SO₃H groups"],"answer":0,"explanation":"The strongly acidic –SO₃H protonates the amino group, giving a zwitterion with salt-like character — hence the high melting point and insolubility in organic solvents. NaOH removes H⁺ from –NH₃⁺ to give the soluble sodium salt. Dilute HCl cannot protonate the sulphonate (the conjugate base of a strong acid), so no new soluble cation forms; intramolecular H-bonding is impossible for para groups.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-99","question":"Benzenediazonium chloride is added to an alkaline solution of 4-methylphenol (p-cresol). The azo compound formed is:","options":["4-Methylphenyl phenyl ether","4-(Phenylazo)phenol","3-Methyl-4-(phenylazo)phenol","4-Methyl-2-(phenylazo)phenol"],"answer":3,"explanation":"Azo coupling is electrophilic substitution, normally para to the –O⁻ group. Here the para position is occupied by CH₃, so the diazonium ion attacks the position ortho to –O⁻, giving 4-methyl-2-(phenylazo)phenol after acidification. The methyl group is not displaced, and O-coupling does not occur under these conditions.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-100","question":"Phthalimide is warmed with Br₂ and aqueous NaOH, and the mixture is then acidified carefully. The product is:","options":["Benzamide","Benzene-1,2-diamine","2-Aminobenzoic acid (anthranilic acid)","Phthalic acid only"],"answer":2,"explanation":"Alkali first opens the imide ring to the phthalamate ion (one –CONH₂ and one –COO⁻ on adjacent carbons). The –CONH₂ group then undergoes Hofmann bromamide degradation, losing its carbonyl carbon as CO₃²⁻ and becoming –NH₂. Acidification gives anthranilic acid, H₂N–C₆H₄–COOH — the industrial route to this dye intermediate.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-101","question":"Nylon-2–nylon-6, a biodegradable polyamide, is a copolymer of:","options":["Ethylenediamine and adipic acid","Glycine and 6-aminohexanoic acid","Glycine and hexamethylenediamine","Alanine and 6-aminohexanoic acid"],"answer":1,"explanation":"The '2' and '6' indicate the two amino-acid units: glycine (H₂N–CH₂–COOH, two carbons) and 6-aminohexanoic acid (H₂N–(CH₂)₅–COOH, six carbons). Their alternating amide links are hydrolysed by microorganisms, making the polymer biodegradable. A diamine–diacid pair would be named with two numbers like nylon-6,6.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-102","question":"Which of the following α-amino acids has TWO chiral carbon atoms?","options":["Threonine, CH₃–CH(OH)–CH(NH₂)–COOH","Serine, HO–CH₂–CH(NH₂)–COOH","Valine, (CH₃)₂CH–CH(NH₂)–COOH","Leucine, (CH₃)₂CH–CH₂–CH(NH₂)–COOH"],"answer":0,"explanation":"In threonine both C-2 (H, NH₂, COOH, CH(OH)CH₃) and C-3 (H, OH, CH₃, CH(NH₂)COOH) carry four different groups, so it has 2² = 4 stereoisomers. Serine, valine and leucine have only the α-carbon as a stereocentre; in valine C-3 carries two identical methyl groups. Isoleucine is the other common amino acid with two stereocentres.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-103","question":"Toluene is nitrated and the para isomer is separated. It is then oxidised with alkaline KMnO₄ (followed by acidification) and finally reduced with Sn/HCl (followed by neutralisation). The final product is:","options":["4-Aminobenzyl alcohol","4-Aminotoluene","4-Nitrobenzoic acid","4-Aminobenzoic acid"],"answer":3,"explanation":"Nitration gives 4-nitrotoluene; KMnO₄ oxidises the side-chain CH₃ to –COOH (4-nitrobenzoic acid) while the nitro group survives. Sn/HCl then reduces –NO₂ to –NH₂ but does not touch –COOH, giving 4-aminobenzoic acid (PABA), used in sunscreens. Doing the reduction before oxidation would expose –NH₂ to KMnO₄.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-amines-biomolecules-104","question":"Pyrrolidine is subjected to exhaustive methylation (excess CH₃I) followed by Hofmann elimination (moist Ag₂O, heat), the sequence being repeated until nitrogen is completely removed. The hydrocarbon obtained and the total moles of CH₃I consumed per mole of pyrrolidine are:","options":["But-1-ene; 3","Buta-1,3-diene; 2","Buta-1,3-diene; 3","Cyclobutene; 2"],"answer":2,"explanation":"Pyrrolidine (a 2° amine) takes 2 CH₃I to become N,N-dimethylpyrrolidinium; the first elimination opens the ring to CH₂=CH–CH₂–CH₂–N(CH₃)₂. This 3° amine takes 1 more CH₃I to give the quaternary salt, and the second elimination gives CH₂=CH–CH=CH₂ + N(CH₃)₃. Total CH₃I = 3 and two eliminations are needed.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-105","question":"Each aldohexose below is oxidised with warm dilute HNO₃ to the corresponding aldaric (dicarboxylic) acid. Which one gives an optically inactive (meso) acid?","options":["D-Glucose","D-Galactose","D-Mannose","D-Idose"],"answer":1,"explanation":"In the Fischer projection of D-galactose the C-2 and C-5 OH groups are both on the right and those of C-3 and C-4 both on the left, so when both ends become –COOH the molecule (mucic acid) has a horizontal mirror plane and is meso. D-Glucaric acid has no symmetry, while D-mannaric and D-idaric acids have only a C₂ axis, so they remain chiral and optically active.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-106","question":"Aspartic acid has pKa values 1.88 (α-COOH), 3.65 (side-chain –COOH) and 9.60 (–NH₃⁺). Its isoelectric point is closest to:","options":["2.77","5.74","6.62","3.65"],"answer":0,"explanation":"At the pI the dominant species is the net-neutral zwitterion, which lies between the two ionisations that create it: the loss of the first and second carboxyl protons. Hence pI = (1.88 + 3.65)/2 ≈ 2.77. Averaging all three or using 3.65 and 9.60 (= 6.62) is a common error; the latter applies to basic amino acids, where the zwitterion lies between the two amino ionisations.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-107","question":"1.056 g of the chloroplatinate of a monoacidic organic base, (BH)₂PtCl₆, leaves 0.390 g of platinum on ignition (Pt = 195, H₂PtCl₆ = 410 g mol⁻¹). The molar mass of the base and a possible formula are:","options":["45 g mol⁻¹; C₂H₇N","118 g mol⁻¹; C₆H₁₈N₂","73 g mol⁻¹; C₄H₁₁N","59 g mol⁻¹; C₃H₉N"],"answer":3,"explanation":"Moles of salt = moles of Pt = 0.390/195 = 0.002, so the molar mass of the salt = 1.056/0.002 = 528 g mol⁻¹. The salt is B₂·H₂PtCl₆, so 2M(B) = 528 − 410 = 118 and M(B) = 59 g mol⁻¹, fitting C₃H₉N (e.g. propan-1-amine or trimethylamine). Forgetting that each Pt carries two base molecules gives 118.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-108","question":"Which pair of reactions gives the SAME amine?","options":["Butanamide + LiAlH₄ followed by H₂O, and propanenitrile + LiAlH₄ followed by H₂O","Propanamide + Br₂/NaOH, and propanenitrile + LiAlH₄ followed by H₂O","Butanamide + Br₂/NaOH, and propanenitrile + LiAlH₄ followed by H₂O","Propanamide + LiAlH₄ followed by H₂O, and ethanenitrile + LiAlH₄ followed by H₂O"],"answer":2,"explanation":"Hofmann degradation removes one carbon: CH₃CH₂CH₂CONH₂ → CH₃CH₂CH₂NH₂. LiAlH₄ reduction of a nitrile keeps all carbons: CH₃CH₂CN → CH₃CH₂CH₂NH₂, so both give propan-1-amine. Propanamide + Br₂/NaOH gives ethanamine; LiAlH₄ on butanamide gives butan-1-amine; propanamide + LiAlH₄ gives propan-1-amine but ethanenitrile gives ethanamine.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-109","question":"Aniline is treated in turn with (i) (CH₃CO)₂O, (ii) conc. HNO₃/conc. H₂SO₄ at 288 K (para product isolated), (iii) aqueous H₂SO₄, heat, (iv) NaNO₂/HCl at 273–278 K and (v) CuBr/HBr. The final product is:","options":["4-Bromoacetanilide","1-Bromo-4-nitrobenzene","1-Bromo-3-nitrobenzene","4-Bromoaniline"],"answer":1,"explanation":"Acetylation moderates the –NH₂ group and protects it from oxidation, so nitration gives mainly 4-nitroacetanilide. Acid hydrolysis frees 4-nitroaniline, which is diazotised to 4-nitrobenzenediazonium ion; the Sandmeyer reaction replaces –N₂⁺ by Br. The product is 4-bromonitrobenzene — a para isomer that direct bromination of nitrobenzene (meta-directing) cannot give.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-110","question":"How many of the following statements are correct? (A) All naturally occurring α-amino acids except glycine are optically active and have the L-configuration. (B) Glycine is an essential amino acid for humans. (C) In strongly acidic solution an amino acid migrates towards the cathode during electrophoresis. (D) Proline contains a secondary amino group. (E) Lysine is an acidic amino acid.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(A) is true: protein amino acids are L, and only glycine is achiral. (C) is true because in strong acid the species is H₃N⁺–CHR–COOH, a cation. (D) is true: proline's N is part of a pyrrolidine ring. (B) is false — the body synthesises glycine — and (E) is false: lysine, with an extra –NH₂, is basic. So three are correct.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-111","question":"Consider all isomers of C₇H₉N that contain a benzene ring. Let x be the number that give a positive carbylamine test, and y the number that, after treatment with NaNO₂/HCl at 273–278 K, give an azo dye with alkaline β-naphthol. Then (x, y) is:","options":["(4, 3)","(5, 3)","(4, 4)","(3, 3)"],"answer":0,"explanation":"The isomers are benzylamine, N-methylaniline and o-, m- and p-toluidine (five in all). The carbylamine test needs a 1° amine: benzylamine and the three toluidines, so x = 4. Only 1° ARYL amines form stable diazonium salts at 0–5 °C, so only the three toluidines give a dye; benzylamine evolves N₂ and N-methylaniline gives an N-nitrosamine. Thus y = 3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-112","question":"A polymer sample contains 30% (by number) of molecules with molar mass 20 000 g mol⁻¹ and 70% with 40 000 g mol⁻¹. Its number-average molar mass (Mn) and polydispersity index (PDI = Mw/Mn) are approximately:","options":["36 470 g mol⁻¹ and 0.93","30 000 g mol⁻¹ and 1.07","34 000 g mol⁻¹ and 1.00","34 000 g mol⁻¹ and 1.07"],"answer":3,"explanation":"Mn = ΣNᵢMᵢ/ΣNᵢ = 0.3 × 20 000 + 0.7 × 40 000 = 34 000. Mw = ΣNᵢMᵢ²/ΣNᵢMᵢ = (0.3 × 4 × 10⁸ + 0.7 × 1.6 × 10⁹)/34 000 ≈ 36 470. PDI = 36 470/34 000 ≈ 1.07; it can never be below 1, and equals 1 only for a monodisperse polymer.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-113","question":"Which statement about lactose is correct?","options":["C-1 of α-D-glucose is linked to C-2 of β-D-fructose, and lactose is non-reducing","C-1 of β-D-galactose is linked to C-4 of D-glucose, and lactose is a reducing sugar","C-1 of α-D-galactose is linked to C-4 of D-glucose, and lactose is non-reducing","C-1 of β-D-glucose is linked to C-4 of D-galactose, and lactose is non-reducing"],"answer":1,"explanation":"Lactose is β-D-galactopyranosyl-(1→4)-D-glucopyranose. Only the anomeric carbon of galactose is tied up in the glycosidic bond; the glucose C-1 remains a free hemiacetal, so lactose mutarotates and reduces Fehling's solution. The C1–C2 linkage between glucose and fructose describes sucrose.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-114","question":"Guanidine, HN=C(NH₂)₂, ethanamine, aniline and acetamide are compared. The correct decreasing order of basic strength is:","options":["Guanidine > ethanamine > aniline > acetamide","Ethanamine > guanidine > aniline > acetamide","Guanidine > aniline > ethanamine > acetamide","Ethanamine > aniline > acetamide > guanidine"],"answer":0,"explanation":"Protonating guanidine at the imino N gives the guanidinium ion, in which the positive charge is spread equally over three N atoms by resonance; this huge stabilisation of the conjugate acid makes guanidine (pKaH ≈ 13.6) a stronger base than alkylamines (pKaH ≈ 10.7). Aniline's lone pair is delocalised into the ring (pKaH ≈ 4.6), and acetamide's into the C=O group, making it almost neutral.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-115","question":"D-Fructose, a ketohexose, reduces Tollens' and Fehling's reagents although simple ketones do not. The main reason is that:","options":["Ketones are always oxidised by Tollens' reagent if they have more than five carbons","Fructose exists mainly as an open-chain aldehyde in water","The furanose ring of fructose contains a free –CHO group","In the alkaline reagent fructose isomerises via an enediol to glucose and mannose (aldoses), and the α-hydroxy ketone is itself readily oxidised"],"answer":3,"explanation":"Base removes an α-H from C-1/C-3 of fructose, giving a 1,2-enediol that reprotonates to D-glucose or D-mannose (Lobry de Bruyn–van Ekenstein rearrangement). These aldoses, and the α-hydroxy ketone grouping itself, reduce Ag⁺ and Cu²⁺. Hence fructose counts as a reducing sugar even though it has no –CHO group.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-116","question":"Benzenediazonium chloride is added to N,N-dimethylaniline in weakly acidic solution. The product, once used as a food colour (butter yellow), is:","options":["N,N-Dimethyl-2-(phenylazo)aniline","N-Nitroso-N-methylaniline","4-(Dimethylamino)azobenzene, C₆H₅–N=N–C₆H₄–N(CH₃)₂","Diazoaminobenzene, C₆H₅–N=N–NH–C₆H₅"],"answer":2,"explanation":"N(CH₃)₂ strongly activates the ring, and with no N–H available N-coupling (as with aniline to give diazoaminobenzene) cannot occur. The diazonium ion attacks the unhindered para carbon, giving p-(dimethylamino)azobenzene (methyl/butter yellow). It was banned as a food colourant because it is carcinogenic.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-117","question":"7.5 g of glycine is treated with excess nitrous acid (Van Slyke method). The volume of N₂ evolved at STP (22.4 L mol⁻¹) and the organic product are:","options":["1.12 L; hydroxyethanoic (glycolic) acid","2.24 L; hydroxyethanoic (glycolic) acid","2.24 L; ethanoic acid","4.48 L; ethane-1,2-diol"],"answer":1,"explanation":"H₂N–CH₂–COOH + HNO₂ → HO–CH₂–COOH + N₂ + H₂O: each free primary –NH₂ group gives one N₂. Glycine (M = 75) is 7.5/75 = 0.1 mol, so 0.1 × 22.4 = 2.24 L N₂. Measuring this N₂ is the basis of Van Slyke's estimation of free amino groups.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-amines-biomolecules-118","question":"One strand of a DNA segment has the sequence 5′-ATGCCG-3′. The complementary strand, written in the conventional 5′→3′ direction, is:","options":["5′-CGGCAT-3′","5′-TACGGC-3′","5′-UACGGC-3′","5′-GCCGTA-3′"],"answer":0,"explanation":"The strands are antiparallel and pair A–T and G–C. Pairing base-by-base gives 3′-TACGGC-5′ opposite the given strand; written from its 5′ end this is 5′-CGGCAT-3′. TACGGC is the same strand written backwards, uracil occurs only in RNA, and GCCGTA is simply the reversed original.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
